import numpy as np,time
for n in range(2,11,2):
 As=[np.random.normal(size=(n,n)).astype(np.float64) for _ in range(500)]
 def b(fn):
  ts=[]
  for A in As:
   t=time.perf_counter(); fn(A);ts.append(time.perf_counter()-t)
  return np.median(ts)*1e6
 def solvev(A):
  w=np.linalg.eigvals(A);l=w[np.argmax(np.abs(w))]; M=A.astype(complex)-l*np.eye(n)
  # eliminate row n and solve top n-1 with RHS from last row
  return np.linalg.solve(M[:-1,:-1],-M[:-1,-1])
 def invv(A):
  w=np.linalg.eigvals(A);l=w[np.argmax(np.abs(w))]; M=A.astype(complex)-l*np.eye(n)
  return np.linalg.inv(M)
 print(n,'eigvals+solve',b(solvev),'eigvals+inv',b(invv))
